typedef unsigned int u_int;
typedef unsigned long long u_long128;

struct sceDmaChan;
struct sceGsDrawEnv1 { unsigned char data[240]; };
struct sceGsDBuff {
    unsigned char pad0[96];
    sceGsDrawEnv1 draw0;
    sceGsDrawEnv1 draw1;
};
struct VoData;
struct VoTag {
    int status;
    int dummy[15];
    unsigned int v[2][39232];
};
struct VoBuf {
    VoData *data;
    VoTag *tag;
    volatile int write;
    volatile int count;
    int size;
};

extern sceDmaChan *sceDmaGetChan(int);
extern int sceGsSyncPath(int, int);
extern VoTag *voBufGetTag(VoBuf *);
extern void sceGsSetHalfOffset(sceGsDrawEnv1 *, int, int, int);
extern void sceGsSwapDBuff(sceGsDBuff *, int);
extern void sceDmaSend(sceDmaChan *, u_long128 *);

extern sceGsDBuff *pGSDB;
extern VoBuf voBuf;
extern int frd;
extern volatile int isCountVblank;
extern volatile int vblankCount;
extern volatile int isFrameEnd;
extern volatile int oddeven;
extern volatile int handler_error;

__asm__(
    ".equ pGSDB,0x00596F50\n"
    ".equ voBuf,0x005970F0\n"
    ".equ frd,0x00596F9C\n"
    ".equ isCountVblank,0x0048AFF4\n"
    ".equ vblankCount,0x0048AFF8\n"
    ".equ isFrameEnd,0x0048AFFC\n"
    ".equ oddeven,0x0048B008\n"
    ".equ handler_error,0x0048B00C\n"
    ".equ sceDmaGetChan__Fi,0x003BAF88\n"
    ".equ sceGsSyncPath__Fii,0x003B9968\n"
    ".equ voBufGetTag__FP5VoBuf,0x00389120\n"
    ".equ sceGsSetHalfOffset__FP13sceGsDrawEnv1iiii,0x003BAC38\n"
    ".equ sceGsSwapDBuff__FP10sceGsDBuffi,0x003BA370\n"
    ".equ sceDmaSend__FP10sceDmaChanPv,0x003BB268\n"
);

#define SCE_DMA_GIF 2
#define GS_CSR ((volatile unsigned long long *)0x12001000)
#define UncAddr(x) ((void *)(((u_int)(x) & 0x0fffffff) | 0x20000000))
#define VOBUF_STATUS_ 0
#define VOBUF_STATUS_TOPDONE 1
#define VOBUF_STATUS_FULL 2
#define ExitHandler() __asm__ volatile("sync.p\n\tei")

static int vblankHandler( int val )
{
    sceDmaChan  *dmaGif_loadimage = sceDmaGetChan( SCE_DMA_GIF );

    oddeven = ( *GS_CSR >> 13 ) & 1;
    if( isCountVblank )
    {
        VoTag   *tag;

        vblankCount++;
        handler_error = sceGsSyncPath( 1, 0 );
        if( !handler_error )
        {
            tag = voBufGetTag( &voBuf );
            if( !tag )
            {
                frd++;
                ExitHandler();
                return 0;
            }
            sceGsSetHalfOffset( (oddeven&1)?(sceGsDrawEnv1*)UncAddr(&pGSDB->draw1) : (sceGsDrawEnv1*)UncAddr(&pGSDB->draw0), 2048, 2048, oddeven ^ 0x1 );
            if( (oddeven == 0) && (tag->status == VOBUF_STATUS_FULL) )
            {
                sceGsSwapDBuff( pGSDB, 0 );
                sceGsSyncPath( 0, 0 );
                sceDmaSend( dmaGif_loadimage, (u_long128*)((u_int)tag->v[0]) );
                tag->status = VOBUF_STATUS_TOPDONE;
            }
            else if( oddeven == 1 && tag->status == VOBUF_STATUS_TOPDONE )
            {
                sceGsSwapDBuff( pGSDB, 1 );
                sceGsSyncPath( 0, 0 );
                sceDmaSend( dmaGif_loadimage, (u_long128*)((u_int)tag->v[1]) );
                tag->status = VOBUF_STATUS_;
                isFrameEnd = 1;
            }
        }
    }
    ExitHandler();
    return 0;
}
